package stowage

// AmendCargo 按货物编号更正一件货物的重量、目的地与混装许可。
//
// 编号与目的地沿用登记规则：去掉首尾空白后不得为空，编号区分大小写；
// weight 必须为正整数（千克）。空编号、货物不存在、非正重量或去空白后
// 目的地为空都按现有结构化错误拒绝；修改不存在的货物不会变成登记。
//
// 三项资料作为一次完整替换生效，内容与现有资料完全相同时同样成功，
// 但不新增货物、不再次占用重量。更正不占用配载调整编号，也不影响已
// 成功调整保存的结果：之后以原编号、原内容重复提交调整，仍返回首次
// 成功时的变化与重量。更正前返回的查询或预览快照继续保留原内容。
//
// 未装载货物只需资料本身合法，更正后仍为未装载。已装载货物按三项新
// 资料共同生效后的最终配载判断，不会因修改某个字段的中间状态不合法
// 而拒绝最终合法的资料：所属舱位先扣除该货物旧重量、再计入新重量，
// 恰好达到承重允许保存，超过承重或合计无法用 int64 表示则拒绝；
// 同舱目的地全部相同时允许不混装的货物共舱，出现不同目的地时所有
// 货物都必须允许混装。
//
// 更正失败时，货物的三项旧资料、所属舱位重量及其他货物全部保留。
func (r *Registry) AmendCargo(id string, weight int64, destination string, allowMixed bool) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := trimID(id)
	if cid == "" {
		return fail(ErrInvalidID, "", "货物编号为空")
	}
	c, ok := r.cargos[cid]
	if !ok {
		return fail(ErrNotFound, cid, "货物 %s 不存在", cid)
	}
	if weight <= 0 {
		return fail(ErrInvalidWeight, cid, "货物 %s 重量必须为正整数千克，当前为 %d", cid, weight)
	}
	dest := trimID(destination)
	if dest == "" {
		return fail(ErrInvalidDestination, cid, "货物 %s 目的地为空", cid)
	}

	// 已装载货物：在所属舱位的模拟配载上替换该货物，按三项资料共同
	// 生效后的最终状态统一判断，而不是逐个字段制造中间状态。
	if c.compartmentID != "" {
		comp := r.compartments[c.compartmentID]
		sim := &cargo{
			id:            c.id,
			weight:        weight,
			destination:   dest,
			allowMixed:    allowMixed,
			compartmentID: comp.id,
		}
		set := make(map[string]*cargo, len(comp.cargo))
		for otherID, other := range comp.cargo {
			if otherID == c.id {
				set[c.id] = sim
			} else {
				set[otherID] = other
			}
		}
		final := map[string]map[string]*cargo{comp.id: set}
		// 拒绝原因到结构化错误的转换与 Adjust 共用；更正不携带调整编号。
		if rej := r.firstRejection(final); rej != nil {
			return rejectionError(rej, fail)
		}
	}

	c.weight = weight
	c.destination = dest
	c.allowMixed = allowMixed
	return nil
}

package stowage

import "fmt"

// ErrorKind 描述一次配载操作失败的具体原因。
type ErrorKind int

const (
	// ErrOK 表示没有错误（内部使用）。
	ErrOK ErrorKind = iota
	// ErrInvalidID 编号去掉首尾空白后为空。
	ErrInvalidID
	// ErrInvalidWeight 重量或最大承重不是正整数。
	ErrInvalidWeight
	// ErrInvalidDestination 目的地去掉首尾空白后为空。
	ErrInvalidDestination
	// ErrInvalidOp 操作种类无法识别。
	ErrInvalidOp
	// ErrAlreadyExists 登记对象已存在。
	ErrAlreadyExists
	// ErrNotFound 涉及的货物或舱位不存在。
	ErrNotFound
	// ErrStateMismatch 货物状态与操作不符（未装载或已装载）。
	ErrStateMismatch
	// ErrDuplicateOp 同一调整中货物重复出现，或移动到原舱位。
	ErrDuplicateOp
	// ErrEmptyAdjustment 调整不包含任何操作。
	ErrEmptyAdjustment
	// ErrOverweight 舱位总重量超过最大承重。
	ErrOverweight
	// ErrMixedLoading 不同目的地货物混装，但有货物不允许混装。
	ErrMixedLoading
	// ErrOverflow 重量合计超过 int64 可表示范围。
	ErrOverflow
	// ErrAdjustmentIDConflict 调整编号已用于不同内容。
	ErrAdjustmentIDConflict
)

// String 返回错误原因的中文说明。
func (k ErrorKind) String() string {
	switch k {
	case ErrInvalidID:
		return "编号为空"
	case ErrInvalidWeight:
		return "重量或承重非正整数"
	case ErrInvalidDestination:
		return "目的地为空"
	case ErrInvalidOp:
		return "操作种类无效"
	case ErrAlreadyExists:
		return "对象已存在"
	case ErrNotFound:
		return "对象不存在"
	case ErrStateMismatch:
		return "状态不符"
	case ErrDuplicateOp:
		return "重复操作"
	case ErrEmptyAdjustment:
		return "调整为空"
	case ErrOverweight:
		return "超重"
	case ErrMixedLoading:
		return "混装冲突"
	case ErrOverflow:
		return "重量溢出"
	case ErrAdjustmentIDConflict:
		return "调整编号冲突"
	default:
		return "未知错误"
	}
}

// Error 是配载操作的结构化失败结果，指出涉及的对象与具体原因。
type Error struct {
	Kind         ErrorKind
	ID           string // 涉及的货物或舱位编号，可能为空
	AdjustmentID string // 涉及的调整编号，可能为空
	detail       string
}

func (e *Error) Error() string {
	if e.detail != "" {
		return e.detail
	}
	return e.Kind.String()
}

// fail 构造一个带说明的结构化错误。
func fail(kind ErrorKind, id string, format string, args ...any) *Error {
	return &Error{Kind: kind, ID: id, detail: fmt.Sprintf(format, args...)}
}

// rejectionError 把最终配载评估出的单个拒绝原因转换成正式操作的结构化
// 错误，Adjust 与 AmendCargo 共用同一套对应关系，保证同一种拒绝原因的
// 错误类别、涉及对象与中文说明一致：
// 重量溢出与超重指向舱位，超重说明保留预计总重量与最大承重，溢出不展示
// 无法表示的合计重量；混装冲突指向舱内编号字典序最靠前的一件不允许
// 混装货物（可能原本就在舱内），说明同时指出舱位与该货物。
// failf 决定错误是否携带调整编号：Adjust 传入盖编号的构造函数，
// AmendCargo 直接传入 fail。
func rejectionError(
	rej *Rejection,
	failf func(kind ErrorKind, id string, format string, args ...any) *Error,
) *Error {
	switch rej.Kind {
	case ErrOverflow:
		return failf(ErrOverflow, rej.CompartmentID, "舱位 %s 重量合计超过 int64 可表示范围", rej.CompartmentID)
	case ErrOverweight:
		return failf(ErrOverweight, rej.CompartmentID,
			"舱位 %s 总重量 %d 千克超过最大承重 %d 千克",
			rej.CompartmentID, rej.UsedWeight, rej.MaxWeight)
	default:
		return failf(ErrMixedLoading, rej.firstOffender(),
			"舱位 %s 存在不同目的地货物，但货物 %s 不允许混装",
			rej.CompartmentID, rej.firstOffender())
	}
}

