1	package stowage
2	
3	import (
4		"math"
5		"reflect"
6		"strings"
7		"testing"
8	)
9	
10	// 本文件为“接近 int64 重量上限时同舱换货”补充自动化回归保障，重点保护
11	// 既有规则：重量合法性（承重、溢出）只按整批操作完成后的最终配载判断，
12	// 原货物与新货物在操作序列中临时共舱、临时合计无法用 int64 表示都不得
13	// 拒绝一个最终合法的换货。换货不是新接口，仍是同一次 Adjust 里的
14	// “卸下 G2 + 装入 G3”，并继续使用既有 Preview 与 Adjust 入口。
15	//
16	// 记号：M = math.MaxInt64。初始 C1 装有 G1（M-20）与 G2（10），
17	// 已用 M-10；G3 尚未装载；三件货物目的地相同，资料本身合法。
18	// 本次只卸下 G2、装入 G3，G1 留在 C1。装入写在卸下之前或之后，
19	// 预览与正式提交结论必须一致。
20	
21	// nearLimitSwapOps 返回两种书写顺序的换货清单：卸下 G2、装入 G3。
22	func nearLimitSwapOps() map[string][]Op {
23		return map[string][]Op{
24			"先卸后装": {
25				{Kind: OpUnload, CargoID: "G2"},
26				{Kind: OpLoad, CargoID: "G3", Target: "C1"},
27			},
28			"先装后卸": {
29				{Kind: OpLoad, CargoID: "G3", Target: "C1"},
30				{Kind: OpUnload, CargoID: "G2"},
31			},
32		}
33	}
34	
35	// newNearLimitSwapRegistry 构造换货前配载：C1 承重由 maxWeight 指定，
36	// G1 重 M-20、G2 重 10 已装入 C1（已用 M-10），G3 重 g3Weight 尚未
37	// 装载；三件货物同目的地（X），资料合法。
38	func newNearLimitSwapRegistry(t *testing.T, maxWeight, g3Weight int64) *Registry {
39		t.Helper()
40		r := NewRegistry()
41		mustRegisterCompartment(t, r, "C1", maxWeight)
42		mustRegisterCargo(t, r, "G1", math.MaxInt64-20, "X", true)
43		mustRegisterCargo(t, r, "G2", 10, "X", true)
44		mustRegisterCargo(t, r, "G3", g3Weight, "X", true)
45		mustAdjust(t, r, "init", []Op{
46			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
47			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
48		})
49		return r
50	}
51	
52	// assertNearLimitBefore 核对换货前 C1：仍装 G1、G2，已用 M-10，
53	// 剩余 maxWeight-(M-10)；G3 未装载。
54	func assertNearLimitBefore(t *testing.T, r *Registry, maxWeight int64) {
55		t.Helper()
56		cpt, err := r.Compartment("C1")
57		if err != nil {
58			t.Fatal(err)
59		}
60		if cpt.MaxWeight != maxWeight ||
61			cpt.UsedWeight != math.MaxInt64-10 ||
62			cpt.RemainingWeight != maxWeight-(math.MaxInt64-10) {
63			t.Fatalf("换货前 C1 重量应为 承重%d/已用%d/剩余%d: %+v",
64				maxWeight, math.MaxInt64-10, maxWeight-(math.MaxInt64-10), cpt)
65		}
66		if got := cargoIDs(*cpt); !reflect.DeepEqual(got, []string{"G1", "G2"}) {
67			t.Fatalf("换货前 C1 应仍装 G1、G2: %v", got)
68		}
69		g3, _ := r.Cargo("G3")
70		if g3.Loaded || g3.CompartmentID != "" {
71			t.Fatalf("换货前 G3 应未装载: %+v", g3)
72		}
73	}
74	
75	// assertNearLimitProfilesUnchanged 核对三件货物的登记重量、目的地与
76	// 混装许可始终不随换货结果改变。
77	func assertNearLimitProfilesUnchanged(t *testing.T, r *Registry, g3Weight int64) {
78		t.Helper()
79		g1, _ := r.Cargo("G1")
80		if g1.Weight != math.MaxInt64-20 || g1.Destination != "X" || !g1.AllowMixed {
81			t.Fatalf("G1 登记资料被改变: %+v", g1)
82		}
83		g2, _ := r.Cargo("G2")
84		if g2.Weight != 10 || g2.Destination != "X" || !g2.AllowMixed {
85			t.Fatalf("G2 登记资料被改变: %+v", g2)
86		}
87		g3, _ := r.Cargo("G3")
88		if g3.Weight != g3Weight || g3.Destination != "X" || !g3.AllowMixed {
89			t.Fatalf("G3 登记资料被改变: %+v", g3)
90		}
91	}
92	
93	// 成功路径（C1 承重 M、G3 重 20）：无论装入写在卸下之前还是之后，
94	// 预览都应判定可提交。先装后卸时 G3 与尚未移出的 G1、G2 临时共舱，
95	// 合计 (M-20)+10+20 = M+10 无法用 int64 表示；合法性只看最终配载
96	// （G1+G3 = M），故不得因临时溢出拒绝。
97	func TestNearLimitSwapPreviewSubmittable(t *testing.T) {
98		for name, ops := range nearLimitSwapOps() {
99			t.Run(name, func(t *testing.T) {
100				r := newNearLimitSwapRegistry(t, math.MaxInt64, 20)
101				pv, err := r.Preview(ops)
102				if err != nil {
103					t.Fatalf("换货最终合计 M 合法，预览不应返回错误: %v", err)
104				}
105				if !pv.Submittable || len(pv.Rejections) != 0 {
106					t.Fatalf("换货应可提交，实际拒绝原因: %+v", pv.Rejections)
107				}
108	
109				// 货物变化按编号字典序：G2 由 C1 变为未装载，G3 由未装载进入 C1。
110				wantChanges := []CargoChange{
111					{CargoID: "G2", From: "C1", To: ""},
112					{CargoID: "G3", From: "", To: "C1"},
113				}
114				if !reflect.DeepEqual(pv.CargoChanges, wantChanges) {
115					t.Fatalf("货物变化错误: got=%+v want=%+v", pv.CargoChanges, wantChanges)
116				}
117	
118				// 只有 C1 受影响。
119				if len(pv.Compartments) != 1 || pv.Compartments[0].ID != "C1" {
120					t.Fatalf("应只列出 C1 的前后配载: %+v", pv.Compartments)
121				}
122				cp := pv.Compartments[0]
123	
124				// 调整前完整保留 G1、G2 与已用重量 M-10。
125				before := cp.Before
126				if got := cargoIDs(before); !reflect.DeepEqual(got, []string{"G1", "G2"}) {
127					t.Fatalf("调整前清单应保留 G1、G2: %v", got)
128				}
129				if before.MaxWeight != math.MaxInt64 ||
130					before.UsedWeight != math.MaxInt64-10 ||
131					before.RemainingWeight != 10 {
132					t.Fatalf("调整前重量应为 承重M/已用M-10/剩余10: %+v", before)
133				}
134				// 调整前清单中的货物保持原所属舱位。
135				for _, cv := range before.Cargo {
136					if !cv.Loaded || cv.CompartmentID != "C1" {
137						t.Fatalf("调整前清单中的 %s 应仍显示装载于 C1: %+v", cv.ID, cv)
138					}
139				}
140	
141				// 预计清单只含 G1、G3，已用 M、剩余 0，且显示为属于 C1。
142				after := cp.After
143				if got := cargoIDs(after); !reflect.DeepEqual(got, []string{"G1", "G3"}) {
144					t.Fatalf("预计清单应只含 G1、G3: %v", got)
145				}
146				if after.MaxWeight != math.MaxInt64 ||
147					after.UsedWeight != math.MaxInt64 ||
148					after.RemainingWeight != 0 {
149					t.Fatalf("预计重量应为 承重M/已用M/剩余0: %+v", after)
150				}
151				for _, cv := range after.Cargo {
152					if !cv.Loaded || cv.CompartmentID != "C1" {
153						t.Fatalf("预计清单中的 %s 应显示装载于 C1: %+v", cv.ID, cv)
154					}
155				}
156	
157				// 预览期间实际配载保持原样：C1 仍是 G1、G2，G3 仍未装载。
158				assertNearLimitBefore(t, r, math.MaxInt64)
159				assertNearLimitProfilesUnchanged(t, r, 20)
160			})
161		}
162	}
163	
164	// 成功路径正式提交：两种书写顺序都应成功，返回的 C1 重量变化必须是
165	// M-10 -> M（不能回绕成负数，也不能漏掉留在 C1 的 G1）；提交后舱位
166	// 清单与货物查询与预计归属一致，G2 记录仍可查询且不再占用重量。
167	func TestNearLimitSwapAdjustSucceeds(t *testing.T) {
168		for name, ops := range nearLimitSwapOps() {
169			t.Run(name, func(t *testing.T) {
170				r := newNearLimitSwapRegistry(t, math.MaxInt64, 20)
171				res, err := r.Adjust("swap-1", ops)
172				if err != nil {
173					t.Fatalf("最终合计 M 恰好达承重，正式提交应成功: %v", err)
174				}
175				if res == nil || res.ID != "swap-1" {
176					t.Fatalf("成功结果应携带编号 swap-1: %+v", res)
177				}
178	
179				// 货物变化：G2 卸下、G3 装入，按编号字典序。
180				wantChanges := []CargoChange{
181					{CargoID: "G2", From: "C1", To: ""},
182					{CargoID: "G3", From: "", To: "C1"},
183				}
184				if !reflect.DeepEqual(res.CargoChanges, wantChanges) {
185					t.Fatalf("货物变化错误: got=%+v want=%+v", res.CargoChanges, wantChanges)
186				}
187	
188				// 舱位重量变化 M-10 -> M：先装后卸时若按中间状态或发生整数
189				// 回绕，这里会得到错误/负值；只按最终配载才是 M。
190				if len(res.CompartmentChanges) != 1 {
191					t.Fatalf("应只列出 C1 的重量变化: %+v", res.CompartmentChanges)
192				}
193				cp := res.CompartmentChanges[0]
194				if cp.CompartmentID != "C1" ||
195					cp.WeightBefore != math.MaxInt64-10 ||
196					cp.WeightAfter != math.MaxInt64 {
197					t.Fatalf("C1 重量变化应为 M-10 -> M，不能回绕或漏掉 G1: %+v", cp)
198				}
199	
200				// 提交后舱位查询：清单只含 G1、G3，已用 M、剩余 0。
201				cpt, _ := r.Compartment("C1")
202				if cpt.MaxWeight != math.MaxInt64 ||
203					cpt.UsedWeight != math.MaxInt64 ||
204					cpt.RemainingWeight != 0 {
205					t.Fatalf("提交后 C1 重量应为 承重M/已用M/剩余0: %+v", cpt)
206				}
207				if got := cargoIDs(*cpt); !reflect.DeepEqual(got, []string{"G1", "G3"}) {
208					t.Fatalf("提交后 C1 应只含 G1、G3: %v", got)
209				}
210	
211				// 货物查询与预计归属一致：G1 留在 C1，G3 进入 C1。
212				g1, _ := r.Cargo("G1")
213				if !g1.Loaded || g1.CompartmentID != "C1" {
214					t.Fatalf("G1 应留在 C1: %+v", g1)
215				}
216				g3, _ := r.Cargo("G3")
217				if !g3.Loaded || g3.CompartmentID != "C1" {
218					t.Fatalf("G3 应已装入 C1: %+v", g3)
219				}
220				// G2 记录仍可查询、为未装载，且不再占用 C1 重量。
221				g2, _ := r.Cargo("G2")
222				if g2.Loaded || g2.CompartmentID != "" {
223					t.Fatalf("G2 应已卸下且记录保留（未装载）: %+v", g2)
224				}
225				assertNearLimitProfilesUnchanged(t, r, 20)
226			})
227		}
228	}
229	
230	// 预览可提交的换货，用同一批操作正式提交后，舱位清单/重量应与预览的
231	// 预计配载逐字段一致（两种顺序都核对）。
232	func TestNearLimitSwapPreviewThenAdjustConsistent(t *testing.T) {
233		for name, ops := range nearLimitSwapOps() {
234			t.Run(name, func(t *testing.T) {
235				r := newNearLimitSwapRegistry(t, math.MaxInt64, 20)
236				pv, err := r.Preview(ops)
237				if err != nil || !pv.Submittable {
238					t.Fatalf("预览应可提交: err=%v rejections=%+v", err, pv)
239				}
240				if _, err := r.Adjust("swap-1", ops); err != nil {
241					t.Fatalf("正式提交应成功: %v", err)
242				}
243				cpt, _ := r.Compartment("C1")
244				after := pv.Compartments[0].After
245				if cpt.UsedWeight != after.UsedWeight ||
246					cpt.RemainingWeight != after.RemainingWeight ||
247					!reflect.DeepEqual(cargoIDs(*cpt), cargoIDs(after)) {
248					t.Fatalf("提交后配载应与预计一致: got=%+v want=%+v", cpt, after)
249				}
250			})
251		}
252	}
253	
254	// 最终超重（可表示）：C1 承重改为 M-1，G3 仍重 20，换货后合计 M
255	// 仍能用 int64 表示但超过承重 1 千克。必须以既有的“超重”原因拒绝，
256	// 说明指出舱位、预计重量 M 与承重 M-1，不能当成溢出，也不能回绕。
257	func TestNearLimitSwapFinalOverweightRejected(t *testing.T) {
258		for name, ops := range nearLimitSwapOps() {
259			t.Run(name, func(t *testing.T) {
260				r := newNearLimitSwapRegistry(t, math.MaxInt64-1, 20)
261				assertNearLimitBefore(t, r, math.MaxInt64-1)
262				compBefore := snapshotCompartments(r, "C1")
263				cargoBefore := snapshotCargo(r, "G1", "G2", "G3")
264	
265				// 预览：仍给出完整预计货物清单，但标为不可提交，原因为超重
266				// （不是溢出），携带预计重量 M、承重 M-1、超出 1。
267				pv, err := r.Preview(ops)
268				if err != nil {
269					t.Fatalf("逐条合法时预览应返回完整结果而非错误: %v", err)
270				}
271				if pv.Submittable || len(pv.Rejections) != 1 {
272					t.Fatalf("最终超重应不可提交且恰有一条原因: %+v", pv)
273				}
274				rej := pv.Rejections[0]
275				if rej.Kind != ErrOverweight || rej.CompartmentID != "C1" {
276					t.Fatalf("应以超重原因指出 C1，实际 %+v", rej)
277				}
278				if rej.MaxWeight != math.MaxInt64-1 ||
279					rej.UsedWeight != math.MaxInt64 ||
280					rej.RemainingWeight != -1 ||
281					rej.Overweight != 1 {
282					t.Fatalf("超重原因应给出 承重M-1/预计M/剩余-1/超出1: %+v", rej)
283				}
284				// 预计清单仍只含 G1、G3（被拒安排也展示预计位置）。
285				after := pv.Compartments[0].After
286				if got := cargoIDs(after); !reflect.DeepEqual(got, []string{"G1", "G3"}) {
287					t.Fatalf("超重时预计货物清单仍应给出: %v", got)
288				}
289				if after.UsedWeight != math.MaxInt64 || after.RemainingWeight != -1 {
290					t.Fatalf("超重（可表示）时预计重量应照常给出 M 与 -1: %+v", after)
291				}
292				// 预览不改实际配载。
293				assertCompartmentsUnchanged(t, r, compBefore)
294				assertCargoUnchanged(t, r, cargoBefore)
295	
296				// 正式提交：返回现有超重结构化错误，说明含舱位、预计重量与承重，
297				// 不返回成功结果。
298				se := submitExpectReject(t, r, "swap-bad", ops)
299				if se.Kind != ErrOverweight || se.ID != "C1" {
300					t.Fatalf("正式提交应报 C1 超重，实际 Kind=%s ID=%q", se.Kind, se.ID)
301				}
302				if se.AdjustmentID != "swap-bad" {
303					t.Fatalf("错误应携带编号 swap-bad，实际 %q", se.AdjustmentID)
304				}
305				msg := se.Error()
306				// 说明应指出舱位 C1，并含预计总重量 M 与最大承重 M-1（十进制），
307				// 证明这是按“最终超重”而不是溢出或回绕数值拒绝。
308				if !strings.Contains(msg, "C1") {
309					t.Fatalf("超重说明应指出舱位 C1: %s", msg)
310				}
311				if !strings.Contains(msg, "9223372036854775807") ||
312					!strings.Contains(msg, "9223372036854775806") {
313					t.Fatalf("超重说明应含预计重量 M 与承重 M-1: %s", msg)
314				}
315	
316				// 整批不生效：G1、G2 留在 C1，G3 仍未装载，资料与舱位重量不变。
317				assertCompartmentsUnchanged(t, r, compBefore)
318				assertCargoUnchanged(t, r, cargoBefore)
319				assertNearLimitProfilesUnchanged(t, r, 20)
320			})
321		}
322	}
323	
324	// 最终溢出（不可表示）：C1 承重为 M，G3 重 21，换货后合计 (M-20)+21 =
325	// M+1 无法用 int64 表示。必须以既有的“重量溢出”原因拒绝，不能当作
326	// 普通超重，也不能返回回绕后的负数。
327	func TestNearLimitSwapFinalOverflowRejected(t *testing.T) {
328		for name, ops := range nearLimitSwapOps() {
329			t.Run(name, func(t *testing.T) {
330				r := newNearLimitSwapRegistry(t, math.MaxInt64, 21)
331				assertNearLimitBefore(t, r, math.MaxInt64)
332				compBefore := snapshotCompartments(r, "C1")
333				cargoBefore := snapshotCargo(r, "G1", "G2", "G3")
334	
335				// 预览：给出预计货物清单并标为不可提交，原因为溢出；溢出时
336				// 预计已用、剩余与超出量沿用现有零值约定，仅给承重 M。
337				pv, err := r.Preview(ops)
338				if err != nil {
339					t.Fatalf("逐条合法时预览应返回完整结果而非错误: %v", err)
340				}
341				if pv.Submittable || len(pv.Rejections) != 1 {
342					t.Fatalf("最终溢出应不可提交且恰有一条原因: %+v", pv)
343				}
344				rej := pv.Rejections[0]
345				if rej.Kind != ErrOverflow || rej.CompartmentID != "C1" {
346					t.Fatalf("应以重量溢出原因指出 C1，实际 %+v", rej)
347				}
348				if rej.MaxWeight != math.MaxInt64 {
349					t.Fatalf("溢出原因应给出承重 M: %+v", rej)
350				}
351				if rej.UsedWeight != 0 || rej.RemainingWeight != 0 || rej.Overweight != 0 {
352					t.Fatalf("溢出时预计已用/剩余/超出应沿用零值约定: %+v", rej)
353				}
354				// 预计货物清单照常返回，但预计已用/剩余重量为零值。
355				after := pv.Compartments[0].After
356				if got := cargoIDs(after); !reflect.DeepEqual(got, []string{"G1", "G3"}) {
357					t.Fatalf("溢出时预计货物清单仍应给出: %v", got)
358				}
359				if after.UsedWeight != 0 || after.RemainingWeight != 0 {
360					t.Fatalf("溢出时预计已用与剩余重量应为零值: %+v", after)
361				}
362				// 预览不改实际配载。
363				assertCompartmentsUnchanged(t, r, compBefore)
364				assertCargoUnchanged(t, r, cargoBefore)
365	
366				// 正式提交：返回现有溢出结构化错误，不返回成功结果，也不报超重。
367				se := submitExpectReject(t, r, "swap-overflow", ops)
368				if se.Kind != ErrOverflow || se.ID != "C1" {
369					t.Fatalf("正式提交应报 C1 重量溢出，实际 Kind=%s ID=%q", se.Kind, se.ID)
370				}
371				if se.AdjustmentID != "swap-overflow" {
372					t.Fatalf("错误应携带编号 swap-overflow，实际 %q", se.AdjustmentID)
373				}
374				if !strings.Contains(se.Error(), "C1") {
375					t.Fatalf("溢出说明应指出舱位 C1: %s", se.Error())
376				}
377	
378				// 整批不生效：G1、G2 留在 C1，G3 仍未装载，资料、舱位重量与
379				// 剩余重量（10）都不改变。
380				assertCompartmentsUnchanged(t, r, compBefore)
381				assertCargoUnchanged(t, r, cargoBefore)
382				assertNearLimitProfilesUnchanged(t, r, 21)
383				cpt, _ := r.Compartment("C1")
384				if cpt.UsedWeight != math.MaxInt64-10 || cpt.RemainingWeight != 10 {
385					t.Fatalf("拒绝后 C1 应仍为 已用M-10/剩余10: %+v", cpt)
386				}
387			})
388		}
389	}
390	
391	// 被最终超重/溢出拒绝的换货不占用调整编号：同一编号改用合法的“仅卸下
392	// G2”应能成功，确保拒绝路径既没生效也没污染编号记录。
393	func TestNearLimitSwapRejectionDoesNotConsumeID(t *testing.T) {
394		// 最终超重形态。
395		r := newNearLimitSwapRegistry(t, math.MaxInt64-1, 20)
396		submitExpectReject(t, r, "swap-retry", []Op{
397			{Kind: OpUnload, CargoID: "G2"},
398			{Kind: OpLoad, CargoID: "G3", Target: "C1"},
399		})
400		if _, err := r.Adjust("swap-retry", []Op{{Kind: OpUnload, CargoID: "G2"}}); err != nil {
401			t.Fatalf("被拒编号不应被占用，合法的仅卸下 G2 应成功: %v", err)
402		}
403		g2, _ := r.Cargo("G2")
404		if g2.Loaded || g2.CompartmentID != "" {
405			t.Fatalf("重试成功后 G2 应已卸下: %+v", g2)
406		}
407	
408		// 最终溢出形态。
409		r2 := newNearLimitSwapRegistry(t, math.MaxInt64, 21)
410		submitExpectReject(t, r2, "swap-retry2", []Op{
411			{Kind: OpLoad, CargoID: "G3", Target: "C1"},
412			{Kind: OpUnload, CargoID: "G2"},
413		})
414		if _, err := r2.Adjust("swap-retry2", []Op{{Kind: OpUnload, CargoID: "G2"}}); err != nil {
415			t.Fatalf("溢出被拒编号不应被占用: %v", err)
416		}
417	}
