func TestNearLimitAmendOverflowRejected(t *testing.T) {
	r := newNearLimitAmendRegistry(t, math.MaxInt64)
	compBefore := snapshotCompartments(r, "C1")
	cargoBefore := snapshotCargo(r, "G1", "G2")

