	if !strings.Contains(msg, "C1") {
		t.Fatalf("溢出说明应指出舱位 C1: %s", msg)
	}
	// 无法表示的合计（回绕为 math.MinInt64）不得出现在说明中。
	if strings.Contains(msg, "-") {
		t.Fatalf("溢出说明不得展示回绕成负数的合计重量: %s", msg)
	}

