	// “最终超重（可表示）”而不是溢出或回绕数值拒绝。
	if !strings.Contains(msg, "C1") ||
		!strings.Contains(msg, "9223372036854775803") || // 预计总重 M-4
		!strings.Contains(msg, "9223372036854775802") { // 最大承重 M-5
